import{_ as p}from"./chunks/image-002.Dp2-bnLm.js";import{_ as l}from"./chunks/image-032._eBok2xC.js";import{_ as i,o,c as s,a3 as n}from"./chunks/framework.DdpBa4_E.js";const a="/ReadBooks/assets/image-033.CoMTe4T6.gif",u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/yan-tie-lun/49-备胡第三十八.md","filePath":"books/yan-tie-lun/49-备胡第三十八.md","lastUpdated":1794316978000}'),r={name:"books/yan-tie-lun/49-备胡第三十八.md"};function _(e,t,g,m,c,d){return o(),s("div",null,[...t[0]||(t[0]=[n('<p>备胡第三十八 【题解】</p><p>本篇围绕征讨匈奴问题展开辩论。大夫认为，圣明天子在上，匈奴却公然侵扰中国边境，因而必须要派兵征讨。贤良指出，匈奴住在沙漠之中，过着茹毛饮血的野兽般生活，中国没有必要用礼义去要求匈奴。大夫进一步指出，中国天子是全天下人的父母，而匈奴却没有臣服，所以中国要加强军备。贤良认为，君主只要得到治国之道，远方异族就会前来归附。大夫辩称中国在东、西、南三方边陲已经消除边患，只有北方匈奴未附，希望能够毕其功于一役，然后再解除军备。贤良以孔子执政为例，说明朝廷应该以仁德使远近归附。大夫担心如果不从事征伐和军备，就难以平息暴力侵害，将黎民百姓推向敌人。贤良痛陈征伐给人民带来的深重灾难，要求朝廷重视《春秋》所强调的“重民”传统。</p><p>大夫曰：“鄙语曰[(1)]：‘贤者容不辱[(2)]。’以世俗言之，乡曲有桀[(3)]，人尚辟之[(4)]。今明天子在上，匈奴公为寇[(5)]，侵扰边境，是仁义犯而藜藿采[(6)]。昔狄人侵太王[(7)]，匡人畏孔子[(8)]，故不仁者，仁之贼也[(9)]。是以县官厉武以讨不义[(10)]，设机械以备不仁[(11)]。”</p><p>【注释】</p><p>[(1)]鄙语：俗话。</p><p>[(2)]容不辱：从容不受辱。</p><p>[(3)]乡曲：乡里。桀：凶恶残暴的人。</p><p>[(4)]辟：通“避”，屏除。</p><p>[(5)]公：公然。寇：《左传·文公七年》：“兵作于内为乱，于外为寇。”</p><p>[(6)]是仁义犯而藜藿采：“采”上原有“不”字，据张敦仁说校删。</p><p>[(7)]太王：古公亶父，为周文王祖父。太王本居于豳，因被狄人所侵，迁到岐山定居，子孙才日益强大。《诗经·大雅·緜》歌颂他由豳迁岐的事迹。《孟子·梁惠王下》：“昔者，太王居邠，去之岐山之下居焉。”</p><p>[(8)]匡人畏孔子：《史记·孔子世家》载：“将适陈，过匡，颜刻为仆，以其策指之曰：‘昔吾入此，由彼缺也。’匡人闻之，以为鲁之阳虎。阳虎尝暴匡人，匡人于是遂止孔子。孔子状类阳虎，拘焉五日。”</p><p>[(9)]贼：贼害。</p><p>[(10)]厉武：整训军队。</p><p>[(11)]机械：军备。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“俗话说：‘贤者从容不受辱。’从世俗角度来说，乡里有穷凶极恶之人，人们尚且要躲避他。如今英明天子在上位，匈奴公然侵犯，骚扰中国边境，这是中国仁义受到侵犯，连藜藿野菜都被别人采摘了。从前狄人侵扰太王，匡人威胁孔子，因此不仁的人，是仁人的祸害。因此朝廷要整训军队来讨伐不义的人，加强军备来预防不仁的人。”</p><p>贤良曰：“匈奴处沙漠之中，生不食之地，天所贱而弃之，无坛宇之居[(1)]，男女之别，以广野为闾里[(2)]，以穹庐为家室[(3)]，衣皮蒙毛[(4)]，食肉饮血，会市行[(5)]，牧竖居[(6)]，如中国之麋鹿耳。好事之臣[(7)]，求其义，责之礼，使中国干戈至今未息，万里设备，此《兔罝》之所刺[(8)]，故小人非公侯腹心干城也[(9)]。”</p><p>【注释】</p><p>[(1)]坛：祭坛。宇：宫室。</p><p>[(2)]广野：广袤的原野。闾里：乡里。</p><p>[(3)]穹（qiónɡ）庐：毡子制成的圆顶帐篷，即蒙古包。</p><p>[(4)]衣皮：以兽皮为衣。蒙毛：指身穿兽毛向外的衣服。</p><p>[(5)]会市行：像赶集市一样行走迁徙。</p><p>[(6)]牧竖：牧童。</p><p>[(7)]好事：喜欢生事。</p><p>[(8)]《兔罝（jū）》：《诗经·周南》中的诗篇。《文选》桓温《荐谯元彦表》刘良注：“殷纣之贤人退处山林，网禽兽而食之。文王举闳夭、泰颠于罝网之中。”这是今文《韩诗》之说，以《兔罝》为刺诗。</p><p>[(9)]腹心干城：见于《诗经·周南·兔罝》：“肃肃兔罝，椓之丁丁。赳赳武夫，公侯干城。肃肃兔罝，施于中林。赳赳武夫，公侯腹心。”干城，指捍卫者。干，盾牌。城，城墙。腹心，亲信，心腹。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>贤良说：“匈奴处于沙漠之中，生于不毛之地，为上天所贱视而加以抛弃，他们没有祭坛，没有宫室处所，没有男女之别，以广袤原野为乡里，以毛毡帐篷为家室，穿着兽皮，有的皮毛外翻，吃兽肉，喝兽血，像赶集市一样追逐水草，像牧童一样随牛羊居住，生活习俗如同中国的麋鹿一般。喜欢生事的朝中大臣，要求匈奴讲仁义，重礼仪，使中国大动干戈，至今没有平息，在边疆万里之外设防备胡，这些大臣就是《诗经·周南·兔罝》所讽刺的对象，所以小人不是公侯的心腹和捍卫者。”</p><p>大夫曰：“天子者，天下之父母也。四方之众，其义莫不愿为臣妾[(1)]；然犹修城郭，设关梁[(2)]，厉武士[(3)]，备卫于宫室[(4)]，所以远折难而备万方者也[(5)]。今匈奴未臣，虽无事，欲释备，如之何？”</p><p>【注释】</p><p>[(1)]臣妾：男为臣，女为妾。</p><p>[(2)]关梁：关隘和津梁。</p><p>[(3)]厉武士：训练武士。</p><p>[(4)]备卫于宫室：指宫廷宿卫。</p><p>[(5)]远折难：远离挫折和灾难。一说，抵御远方来犯的敌患。备万方：防备来自各方的祸患。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“天子是天下的父母。四面八方的民众，按道理说没有不愿意做天子的臣妾；然而还要修筑城郭，设置关隘津梁，整训武士，在皇宫周围部署御林禁卫军，这是因为要远离灾难，防备各方面的祸患。如今匈奴尚未臣服，虽然没有发生战争，但你们却想放弃防备，如果有事那该怎么办？”</p><p>贤良曰：“吴王所以见禽于越者[(1)]，以其越近而陵远也[(2)]。秦所以亡者，以外备胡、越而内亡其政也。夫用军于外，政败于内，备为所患[(3)]，增主所忧。故人主得其道，则遐迩偕行而归之[(4)]，文王是也；不得其道，则臣妾为寇[(5)]，秦王是也。夫文衰则武胜，德盛则备寡。”</p><p>【注释】</p><p>[(1)]吴王：指夫差。见：被。禽：同“擒”。</p><p>[(2)]越近：越过近邻越国。陵远：欺凌远方，与远方齐国争上风。吴王夫差不听伍子胥劝谏，放弃心腹大患越国，北上与齐、晋等国争夺霸主地位，最终被越国消灭。陵，通“凌”。</p><p>[(3)]备为所患：对外防备是为了对付所忧患的强敌。</p><p>[(4)]遐迩：远近。偕行：原作“潜行”，据王利器说校改。偕行，一道出行。</p><p>[(5)]臣妾为寇：指宦官赵高将秦二世杀死。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>贤良说：“吴王夫差之所以被越人消灭，是因为他越过近在身边的心腹大患越国，与远方齐国争上风。秦王朝之所以灭亡，是因为对外防备匈奴和百越，对内失去善政。对外用兵，内政失败，对外防备本来是为了对付所忧患的强敌，反而增添了君主的担忧。君主得到治国正道，那么远近民众就一同前来归附，周文王就是这样的人啊；君主不得治国正道，那么身边的臣妾都会成为敌寇，秦王就是这样的人啊。文治衰败，武功就会取胜，道德兴盛，军备就会减少。”</p><p>大夫曰：“往者，四夷俱强，并为寇虐：朝鲜逾徼[(1)]，劫燕之东地[(2)]；东越越东海[(3)]，略浙江之南[(4)]；南越内侵，滑服令[(5)]；氐、僰、冉、</p><p><img src="'+l+'" alt="" loading="lazy"></p><p>、巂唐、昆明之属[(6)]，扰陇西、巴、蜀。今三垂已平[(7)]，唯北边未定。夫一举则匈奴震惧，中外释备，而何寡也[(8)]？”</p><p>【注释】</p><p>[(1)]逾徼（jiào）：越过边境。徼，边境。</p><p>[(2)]劫：掠夺。</p><p>[(3)]东越越东海：原本无第二个“越”字，据陈遵默说校补。</p><p>[(4)]略：攻占。</p><p>[(5)]滑：通“猾”，扰乱。服令：地名，指岭南地区，一作“服领”。</p><p>[(6)]氐：古代少数民族，又称西戎，分布在今青海、甘肃、四川等地。僰（bó）：原本误分为“棘人”二字，据王利器说校改。僰是先秦时期居住在西南的少数民族。冉：古代少数民族，居住在今四川境内。</p><p><img src="'+l+'" alt="" loading="lazy"></p><p>（mánɡ）：古代少数民族，居住在今四川境内。巂（xī）唐：古代少数民族，在今云南保山。</p><p>[(7)]三垂：指东、南、西三方边陲。垂，通“陲”。</p><p>[(8)]夫一举则匈奴震惧，中外释备，而何寡也：原作“夫一举则匈奴中外震惧，备而何寡也”，据王先谦说校改。释备，解除军备。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“从前，四方蛮夷都很强盛，共同成为中国的祸害：朝鲜越过边境，洗劫燕国东部地区；东越越过东海，攻占浙江南部；南越向内地侵犯，扰乱服令地区；氐人、僰人、冉人、</p><p><img src="'+l+'" alt="" loading="lazy"></p><p>人、巂唐人以及昆明等少数民族，侵扰甘肃西部、重庆、四川。如今东、西、南三方边陲已经平定，只有北边匈奴没有臣服。只要打一次胜仗，匈奴就会震慑恐惧，中国和外国军备都可以解除，你还说什么减少呢？”</p><p>贤良曰：“古者，君子立仁修义，以绥其民[(1)]，故迩者习善，远者顺之。是以孔子仕于鲁，前仕三月及齐平[(2)]，后仕三月及郑平[(3)]，务以德安近而绥远。当此之时，鲁无敌国之难，邻境之患。强臣变节而忠顺[(4)]，故季桓隳其都城[(5)]。大国畏义而合好[(6)]，齐人来归郓、</p><p><img src="'+a+'" alt="" loading="lazy"></p><p>、龟阴之田[(7)]。故为政而以德，非独辟害折冲也[(8)]，所欲不求而自得。今百姓所以嚣嚣[(9)]，中外不宁者，咎在匈奴[(10)]。内无室宇之守，外无田畴之积，随美草甘水而驱牧，匈奴不变业[(11)]，而中国以骚动矣[(12)]。风合而云解[(13)]，就之则亡[(14)]，击之则散，未可一世而举也[(15)]。”</p><p>【注释】</p><p>[(1)]绥：安定，安抚。</p><p>[(2)]前仕三月及齐平：《史记·孔子世家》载：“其后定公以孔子为中都宰，一年，四方皆则之。由中都宰为司空，由司空为大司寇。定公十年春，及齐平。”孔子于鲁定公九年（前501）为中都宰，又为司空，再为大司寇。鲁定公十四年（前496），孔子以大司寇摄相事。平，和好。</p><p>[(3)]后仕三月及郑平：《春秋公羊传·定公十一年》载：“冬，及郑平。”鲁定公十一年为公元前499年。</p><p>[(4)]强臣：指孟孙氏、叔孙氏、季孙氏三家。变节：改变节操，指三家向公室屈服。</p><p>[(5)]季桓：鲁国执政大夫季桓子。隳其都城：孔子执政期间，推行打击三桓政策。鲁定公十三年（前497），迫使季桓子平毁费邑，迫使叔孙氏平毁郈（hòu）邑。</p><p>[(6)]畏义：畏惧孔子仁义。合好：与鲁国修好。</p><p>[(7)]齐人来归郓（yùn）、</p><p><img src="'+a+'" alt="" loading="lazy"></p><p>（huān）、龟阴之田：《春秋·定公十年》载：“齐人来归郓、</p><p><img src="'+a+'" alt="" loading="lazy"></p><p>、龟阴田。”杜预注：“三邑皆汶阳田也。奉山县北有龟山，阴，田在其北也。会夹谷，孔子相，齐人服义而归鲁田。”</p><p>[(8)]辟：通“避”。折冲：本义是使战车折回，此处指挫败对手。</p><p>[(9)]嚣嚣（áo）：即“嗸嗸”，众怨之声。</p><p>[(10)]咎：过错。</p><p>[(11)]变业：改变赖以生存的畜牧产业。</p><p>[(12)]以：通“已”。</p><p>[(13)]风合而云解：像风一样聚合，像云彩一样散开，言其聚散不定。</p><p>[(14)]亡：逃亡。</p><p>[(15)]一世：三十年。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>贤良说：“古时候，君子修行仁义道德，来安定民众，因此近处的人通过习染而向善，远处的人则前来归顺。所以孔子担任鲁国大司寇，上任前三月鲁国就与齐讲和修好，后三个月与郑国讲和修好，务求用仁德安定近处的人，平定远处的人。孔子当政的时候，鲁国没有敌国灾难，也没有邻国边境的祸患。三桓强臣不得不改变节操，对公室忠诚顺从，因而季桓子平毁了都城费邑。邻近大国畏惧孔子仁义，对鲁国表示友好，齐国人前来归还郓、</p><p><img src="'+a+'" alt="" loading="lazy"></p><p>、龟阴的土地。因此为政要依靠仁德，并不仅仅是逃避祸害或挫败对手，心里所想得到的东西不去主动追求而自然得到。如今中国老百姓怨声载道，中外不能安宁，其中的过错就在于对匈奴的政策之上。匈奴内无宫室屋宇需要看守，外无种田耕地的积蓄，他们追随肥美的牧草和甘甜的水源而驱赶放牧，匈奴人不改变他们赖以生存的畜牧业，而中国早已为此纷扰骚动了。他们像阵风一样聚合，又像乌云一样解散，靠近他们，他们就逃走，攻击他们，他们就作鸟兽散，不可能几十年就征服他们。”</p><p>大夫曰：“古者，明王讨暴卫弱，定倾扶危。卫弱扶危[(1)]，则小国之君悦；讨暴定倾，则无罪之人附。今不征伐，则暴害不息；不备，则是以黎民委敌也[(2)]。《春秋》贬诸侯之后[(3)]，刺不卒戍[(4)]。行役戍备，自古有之，非独今也。”</p><p>【注释】</p><p>[(1)]卫弱扶危：此四字原本所无，据王利器说校补。</p><p>[(2)]委敌：丢给敌人。</p><p>[(3)]《春秋》贬诸侯之后：指《春秋公羊传》讽刺中国诸侯为它国戍守而后至。后，后到，迟到。</p><p>[(4)]刺不卒戍：《春秋公羊传·僖公二十八年》：“公子买戍卫，不卒戍，刺之。”</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫说：“古时候，英明的君王征讨残暴的国家，保卫弱小的国家，安定衰败的国家，扶持危险的国家。保卫弱小的国家，扶持危险的国家，小国之君就会喜悦；征讨残暴的国家，安定衰败的国家，无罪之人就会归附。如今不征伐，残暴祸害就不会止息；不加强战备，就是把黎民百姓推给敌人。《春秋》讽刺中国诸侯为它国戍守而后至，讽刺没有完成戍守任务的大夫。出征兵役，戍守备战，自古以来就有，并不是只有今天才有。”</p><p>贤良曰：“匈奴之地广大，而戎马之足轻利，其势易骚动也。利则虎曳[(1)]，病则鸟折[(2)]，辟锋锐而取罢极[(3)]；少发则不足以更适[(4)]，多发则民不堪其役[(5)]。役烦则力罢，用多则财乏。二者不息[(6)]，则民遗怨[(7)]。此秦之所以失民心、陨社稷也[(8)]。古者，天子封畿千里[(9)]，繇役五百里，胜声相闻[(10)]，疾病相恤。无过时之师，无逾时之役。内节于民心[(11)]，而事适其力。是以行者劝务[(12)]，而止者安业[(13)]。今山东之戎马甲士戍边郡者，绝殊辽远，身在胡、越，心怀老母。老母垂泣，室妇悲恨，推其饥渴，念其寒苦。《诗》云[(14)]：‘昔我往矣，杨柳依依[(15)]。今我来思[(16)]，雨雪霏霏[(17)]。行道迟迟[(18)]，载渴载饥[(19)]。我心伤悲，莫之我哀[(20)]。’故圣人怜其如此，闵其久去父母妻子[(21)]，暴露中野[(22)]，居寒苦之地，故春使使者劳赐[(23)]，举失职者[(24)]，所以哀远民而慰抚老母也。德惠甚厚，而吏未称奉职承诏以存恤[(25)]，或侵侮士卒，兴之为市[(26)]，并力兼作[(27)]，使之不以理[(28)]。故士卒失职[(29)]，而老母妻子感恨也。宋伯姬愁思而宋国火[(30)]，鲁妾不得意而鲁寝灾[(31)]。今天下不得其意者，非独西宫之女、宋之老母也[(32)]。《春秋》动众则书[(33)]，重民也。宋人围长葛[(34)]，讥久役也。君子之用心必若是。”</p><p>大夫默然不对。</p><p>【注释】</p><p>[(1)]利则虎曳（yè）：有利之时如同老虎撕拉猎物。</p><p>[(2)]病则鸟折：不利之时就像鸟儿折翅伤翼。病，不利，失败。</p><p>[(3)]辟锋锐而取罢极：避开精锐兵锋，攻击疲惫至极的军队。辟，通“避”。取，原作“牧”，据王利器说校改。罢，同“疲”。</p><p>[(4)]少发：少派出征军队。更适：轮流更换执行任务。</p><p>[(5)]堪：承受。役：兵役。</p><p>[(6)]二者：指役烦、用多。</p><p>[(7)]遗怨：留下怨恨。</p><p>[(8)]此秦之所以失民心、陨社稷也：“以”字原无，据王利器说校补。</p><p>[(9)]封畿（jī）：指京都及其四周的土地。</p><p>[(10)]胜声：传出的声音。胜，通“謄”，传。一说，胜声，胜利的消息。</p><p>[(11)]内节：内部调节。</p><p>[(12)]行者：出征将士。劝务：勉力完成任务。</p><p>[(13)]止者：征人留在家中的家属。</p><p>[(14)]《诗》云：此诗见于《诗经·小雅·采薇》。</p><p>[(15)]依依：柳条随风披拂的样子。</p><p>[(16)]思：语尾助词。</p><p>[(17)]雨：用做动词，落。霏霏：雪大的样子。</p><p>[(18)]迟迟：行走缓慢的样子。</p><p>[(19)]载渴载饥：又渴又饥。</p><p>[(20)]之：当作“知”。</p><p>[(21)]闵：同“悯”，怜悯。</p><p>[(22)]中野：原野之中。</p><p>[(23)]劳赐：慰劳赏赐。</p><p>[(24)]举失职者：举用失所的人。</p><p>[(25)]未称：不称职。奉职：奉行职责。承诏：接受诏书。存恤：存问，体恤，关怀。</p><p>[(26)]兴之为市：在军中设立集市。</p><p>[(27)]并力：合力。兼作：一人同时兼负数人责任。</p><p>[(28)]使之不以理：不按道理使用士卒。</p><p>[(29)]故士卒失职：“故”下原有“也”字，且属上为句，写作“使之不以理故也”，现据俞樾说校删“也”字，“故”属下句。</p><p>[(30)]宋伯姬愁思而宋国火：《汉书·五行志上》：“董仲舒以为伯姬如宋，五年，宋恭公卒，伯姬幽居守节，三十余年，又忧患国家之患祸，积阴生阳，故火生灾也。”</p><p>[(31)]鲁妾不得意而鲁寝灾：鲁僖公娶楚女为夫人，结果齐女在楚女之先嫁到鲁国，齐国胁迫鲁僖公以齐女为夫人，以楚女为妾。鲁寝，鲁国宫寝，指楚妾居住的西宫。</p><p>[(32)]西宫之女：即楚女，鲁僖公之妾。宋之老母：宋伯姬。</p><p>[(33)]动众：动用民众从事徭役。书：记载。</p><p>[(34)]宋人围长葛：《春秋公羊传·隐公六年》：“冬，宋人取长葛。外取邑不书，此何以书？久也。”</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>贤良说：“匈奴所居地域广大，骑兵行动轻便敏捷，就其形势来说容易骚扰中国。有利之时他们如同老虎撕拉猎物，不利之时就像鸟儿折翅伤翼，作战时往往避开精锐兵锋，攻击疲惫至极的军队；中国如果少派出征军队就不足轮流更换执行任务，如果多派军队民众又难以承受兵役。兵役繁多民众就会精疲力竭，军事费用太多就会导致财用匮乏。繁重的兵役和军费两者如果不停息，民众就会心生怨恨。这就是秦王朝失去民心、陨灭社稷的原因啊。古时候，天子直辖的王畿方圆千里，服徭役的地方在方圆五百里以内，民众的声音互相可以听到，有了疾病也可以互相关心。没有超越时限的军队，也没有超过时间的徭役。朝廷根据民心在内部调节计划，徭役事务适合民众的承受能力。所以行役的征夫勉力完成任务，留在家里的人安居乐业。现在，来自崤山以东的戎马将士戍守边疆，路途遥远，他们身在胡、越之地，心里怀念家中的老母。老母在家中流泪，妻子伤悲离别，推想良人的饥渴，念叨征夫的寒苦。《诗经·小雅·采薇》写道：‘从前我到前方去，杨柳依依复殷殷。如今战罢把家归，落雪霏霏伤人心。我在路上慢慢走，又是口渴又是饥。我的心里真痛苦，无人知我心中哀。’因此圣主同情征人如此悲苦，怜悯他们久久离开父母妻子，身体暴露于旷野之中，住在寒苦之地，所以春天派使者到前线慰劳赏赐，举用失所的人，这是明主悲哀远方征人、抚慰老母的办法。皇上仁德恩惠是十分丰厚的，可是不称职的官吏却不能按照诏书来关怀战士，有的官员侵犯侮辱士卒，在军中设立集市，让一人兼负多人责任，不按照道理使唤士卒。因此士卒失去应得的待遇，家中的老母妻子感怀愤恨。宋国伯姬幽愁悲思而导致宋国失火，鲁君楚妾不得意而招致鲁国西宫生灾。当今天下不得意的人，远不止像西宫楚妾、宋国老媪那样的人。《春秋》的记载体例是，诸侯如果兴师动众就载于史册，这是体现重视民众的宗旨。《春秋》记载宋人包围长葛，就是讥刺宋国徭役时间太久。君子的用心必定是像这般良苦。”</p><p>大夫沉默，不作回答。</p>',149)])])}const T=i(r,[["render",_]]);export{u as __pageData,T as default};
